import generated from './__generated__/formats.json';

/// The public round-format catalog — ONE list, merged from two halves.
///
/// FACTS (`__generated__/formats.json`) come from the app's
/// `RoundFormat` enum and `roundFormatMeta`, generated by
/// `test/parity/round_formats_catalog_test.dart` in fairwayiq-flutter.
/// Team size, whether a format is a team format, and whether it can be
/// one stretch of a segmented round are all decided there.
///
/// PROSE lives below. It is marketing copy, not configuration, so it
/// has no business in the app — the same split as `leagueCreate.ts`'s
/// BLURBS.
///
/// WHY THIS MODULE EXISTS. Until 2026-10-02 `/tournaments` hand-
/// maintained its own list of 12 formats while the app had 20, and
/// `buddies-trips.astro` linked to it as "See all tournament formats".
/// Two-Man Total shipped on 10-01 and never arrived. The same page
/// carried a SECOND list (`roundFormatLabels`) that was incomplete in
/// a different way. `roundFormats.test.ts` now fails if any format in
/// the generated file has no entry here, so the list cannot fall
/// behind silently again.

export interface RoundFormatFacts {
  code: string;
  label: string;
  teamSize: number;
  isTeamFormat: boolean;
  handicapAllowance: number | null;
  allowanceEngineOwned: boolean;
  v1Available: boolean;
  segmentable: boolean;
}

interface Prose {
  /// Display name for the catalog. Usually the app's label; occasionally
  /// expanded for a reader who has never heard the term.
  name: string;
  /// Short form for dense surfaces like the Cup round tables.
  shortName?: string;
  /// Roster shape, when it is not obvious from the team size alone.
  players?: string;
  body: string;
  /// Written out rather than computed from `handicapAllowance`,
  /// because the engine-owned ones are combination rules (50% of
  /// combined, 60/40, 25/20/15/10) that a single number cannot say.
  allowance?: string;
}

