export interface RoundFormatEntry extends RoundFormatFacts, Prose {
  kind: 'individual' | 'team';
}

const FACTS = generated.formats as RoundFormatFacts[];

/// Every format the app can run, in the app's own order.
///
/// Throws on a missing entry rather than skipping it. A silent skip is
/// how the list fell eight formats behind in the first place, and a
/// build that fails is cheaper than a page that lies.
export const ROUND_FORMATS: RoundFormatEntry[] = FACTS.map((f) => {
  const prose = PROSE[f.code];
  if (!prose) {
    throw new Error(
      `roundFormats.ts has no copy for "${f.code}" (${f.label}). ` +
        'A new format reached __generated__/formats.json without web copy. ' +
        'Add an entry to PROSE — see roundFormats.test.ts.',
    );
  }
  // `teamSize`, NOT `isTeamFormat`. The app's flag is narrower than a
  // reader's sense of the word: Round Robin, Six-Six-Six and
  // Bloodsome are all `isTeamFormat: false` because they do not use
  // the team-scoring surfaces, yet every one of them is played in
  // pairs. Deriving from the flag would have quietly moved three
  // partner formats into "Individual formats" on this page.
  return { ...f, ...prose, kind: f.teamSize > 1 ? 'team' : 'individual' };
});

/// Wire code → short display label, for dense surfaces like the Cup
/// round tables. Derived, so it cannot disagree with the catalog.
export const roundFormatLabels: Record<string, string> = Object.fromEntries(
  ROUND_FORMATS.map((f) => [f.code, f.shortName ?? f.name]),
);

/// Formats that can be ONE STRETCH of a round that changes format
/// partway (holes 1–6 alt-shot, 7–12 best ball, 13–18 two-man total).
export const SEGMENTABLE_FORMATS = ROUND_FORMATS.filter((f) => f.segmentable);

/// The number the app actually ships, for the "N side games" lines.
export const SIDE_GAME_COUNT: number = generated.sideGameCount;
export const ROUND_FORMAT_COUNT: number = generated.formatCount;
